/**
 * @title pathObject2Object
 * @description 根据路径获取值
 * @param { ObjectType } record 数据
 * @param { PathConf } [conf]
 * @returns { ObjectType }
{
  "a.b.c": 1,
  "a.e.0": 3,
  "a.e.1": 4
}
=>
{
a: {
  b: {
    c: 1
  },
    e: [3, 4]
  }
}
 */
function pathObject2Object(record, conf) {
    const result = {};
    const { gap = '.' } = getConf(conf);
    const init = (keys, value, record) => {
        if (keys.length === 1)
            record[keys[0]] = value;
        if (keys.length > 1) {
            const [key, ...restKey] = keys;
            if (!record[key])
                record[key] = {};
            init(restKey, value, record[key]);
            if (Object.keys(record[key]).filter((n) => isNumber(Number(n))).length) {
                const tmp = [];
                for (const i in record[key])
                    tmp[i] = record[key][i];
                record[key] = tmp;
            }
        }
    };
    for (const key in record)
        init(key.split(gap), record[key], result);
    return result;
}
