/**
 * @title setPathKeyValue
 * @description 根据 pathKey 设置 值
 * @param {ObjectType} record
 * @param {PathConf} conf
 * @param {any} value
 */
function setValueByPath(record, conf, value) {
    const { path, gap } = getConf(conf);
    const cb = (obj, keys) => {
        const [key, ...restKeys] = keys;
        try {
            if (!obj[key]) {
                if (isNumber(Number(key))) {
                    obj[key] = [];
                }
                else {
                    obj[key] = {};
                }
            }
            if (restKeys.length) {
                cb(obj[key], restKeys);
                return;
            }
            obj[key] = value;
        }
        catch (error) {
            console.error(error);
        }
    };
    if (isString(path)) {
        cb(record, path.split(gap));
    }
    else if (isNumber(path)) {
        cb(record, [path.toString()]);
    }
}
